--AVG_CURRENT, LP_STATUS, IS_RECORD_EDITED, cast( RECORD_STATUS as integer) RECORD_STATUS, CREATED_BY, CREATE_DATE, UPDATE_BY, UPDATE_DATE, SERVER_IP, MTR_NUMBER, IR_CURRENT, IY_CURRENT, IB_CURRENT, VRN_VOLTAGE, VYN_VOLTAGE, VBN_VOLTAGE, KW_EXP, KVA_EXP, 
--NEUTRAL_CURRENT, AVERAGE_SIGNAL_STRENGTH, METER_MASTER_ID, VArh_Q1, VArh_Q2, VArh_Q3, VArh_Q4, REQUEST_TIME,
-- RESPONSE_TIME, FILE_NAME, SOURCE_TYPE, NEW_COM_ID, AVG_TEMPERATURE, SIGNED_AVG_PF, ACT_POWER, APP_POWER, REA_POWER_LAG, REA_POWER_LEAD, KVARH_EXP
